def binary_gap(n):
    b = bin(n)[2:]
    best = run = 0
    for c in b[1:]:
        if c == '1':
            if run > best:
                best = run
            run = 0
        else:
            run += 1
    return best

def ttt_winner(board):
    lines = list(board)
    lines += [''.join(board[r][c] for r in range(3)) for c in range(3)]
    lines.append(''.join(board[i][i] for i in range(3)))
    lines.append(''.join(board[i][2 - i] for i in range(3)))
    for p in 'XO':
        if any(line == p * 3 for line in lines):
            return p
    if all(c != '.' for row in board for c in row):
        return 'Draw'
    return 'Playing'

def wrap_text(text, width):
    lines, cur = [], ''
    for w in text.split():
        if not cur:
            cur = w
        elif len(cur) + 1 + len(w) <= width:
            cur += ' ' + w
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return '\n'.join(lines)

def phone_letters(digits):
    m = {'2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
         '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'}
    if not digits:
        return []
    combos = ['']
    for d in digits:
        combos = [p + c for p in combos for c in m[d]]
    return combos

def zigzag(s, rows):
    if rows == 1 or rows >= len(s):
        return s
    out = [''] * rows
    r, step = 0, 1
    for c in s:
        out[r] += c
        if r == 0:
            step = 1
        elif r == rows - 1:
            step = -1
        r += step
    return ''.join(out)

from math import gcd

def fraction_add(a, b):
    def parse(f):
        p, q = f.split('/')
        return int(p), int(q)
    p1, q1 = parse(a)
    p2, q2 = parse(b)
    num = p1 * q2 + p2 * q1
    den = q1 * q2
    if num == 0:
        return '0/1'
    g = gcd(abs(num), den)
    return f'{num // g}/{den // g}'

def day_of_week(date):
    y, m, d = (int(x) for x in date.split('-'))
    if m < 3:
        m += 12
        y -= 1
    k, j = y % 100, y // 100
    h = (d + 13 * (m + 1) // 5 + k + k // 4 + j // 4 + 5 * j) % 7
    return ['Saturday', 'Sunday', 'Monday', 'Tuesday',
            'Wednesday', 'Thursday', 'Friday'][h]
